use std :: fmt :: Display ; use std :: ops :: Deref ; use derive_more :: derive :: { Display , From } ; use derive_setters :: Setters ; use forge_template :: Element ; use serde :: { Deserialize , Serialize } ; use tracing :: debug ; use super :: { ToolCallFull , ToolResult } ; use crate :: temperature :: Temperature ; use crate :: top_k :: TopK ; use crate :: top_p :: TopP ; use crate :: { Attachment , AttachmentContent , ConversationId , EventValue , Image , MessagePhase , ModelId , ReasoningFull , ToolChoice , ToolDefinition , ToolOutput , ToolValue , Usage , } ; use TokenCount :: * ; use insta :: assert_yaml_snapshot ; use pretty_assertions :: assert_eq ; use super :: * ; use crate :: transformer :: Transformer ; use crate :: { DirectoryEntry , FileInfo , estimate_token_count } ; impl Context { pub fn accumulate_usage (& self) -> Option < Usage > { self . messages . iter () . filter_map (| msg | msg . usage . as_ref ()) . cloned () . reduce (| a , b | a . accumulate (& b)) } pub fn system_prompt (& self) -> Option < & str > { self . messages . iter () . find (| message | message . has_role (Role :: System)) . and_then (| msg | msg . content ()) } pub fn add_base64_url (mut self , image : Image) -> Self { self . messages . push (ContextMessage :: Image (image) . into ()) ; self } pub fn add_tool (mut self , tool : impl Into < ToolDefinition >) -> Self { let tool : ToolDefinition = tool . into () ; self . tools . push (tool) ; self } pub fn add_message (self , content : impl Into < ContextMessage >) -> Self { self . add_entry (content . into ()) } pub fn add_entry (mut self , content : impl Into < MessageEntry >) -> Self { let content = content . into () ; self . messages . push (content) ; self } pub fn add_attachments (self , attachments : Vec < Attachment > , model_id : Option < ModelId >) -> Self { attachments . into_iter () . fold (self , | ctx , attachment | { ctx . add_message (match attachment . content { AttachmentContent :: Image (image) => ContextMessage :: Image (image) , AttachmentContent :: FileContent { content , info } => { let elm = Element :: new ("file_content") . attr ("path" , attachment . path) . attr ("start_line" , info . start_line) . attr ("end_line" , info . end_line) . attr ("total_lines" , info . total_lines) . cdata (content) ; let mut message = TextMessage :: new (Role :: User , elm . to_string ()) . droppable (true) ; if let Some (model) = model_id . clone () { message = message . model (model) ; } message . into () } AttachmentContent :: DirectoryListing { entries } => { let elm = Element :: new ("directory_listing") . attr ("path" , attachment . path) . append (entries . into_iter () . map (| entry | { let tag_name = if entry . is_dir { "dir" } else { "file" } ; Element :: new (tag_name) . text (entry . path) })) ; let mut message = TextMessage :: new (Role :: User , elm . to_string ()) . droppable (true) ; if let Some (model) = model_id . clone () { message = message . model (model) ; } message . into () } }) }) } pub fn add_tool_results (mut self , results : Vec < ToolResult >) -> Self { if ! results . is_empty () { debug ! (results = ? results , "Adding tool results to context") ; self . messages . extend (results . into_iter () . map (ContextMessage :: tool_result) . map (MessageEntry :: from) ,) ; } self } # [doc = " Updates the set system message"] pub fn set_system_messages < S : Into < String > > (mut self , content : Vec < S >) -> Self { if self . messages . is_empty () { for message in content { self . messages . push (ContextMessage :: system (message . into ()) . into ()) ; } self } else { self . messages . retain (| m | ! m . has_role (Role :: System)) ; for message in content . into_iter () . rev () { self . messages . insert (0 , ContextMessage :: system (message . into ()) . into ()) ; } self } } # [doc = " Converts the context to textual format"] pub fn to_text (& self) -> String { let mut lines = String :: new () ; for message in self . messages . iter () { lines . push_str (& message . to_text ()) ; } format ! ("<chat_history>{lines}</chat_history>") } # [doc = " Will append a message to the context. This method always assumes tools"] # [doc = " are supported and uses the appropriate format. For models that don't"] # [doc = " support tools, use the TransformToolCalls transformer to convert the"] # [doc = " context afterward."] # [allow (clippy :: too_many_arguments)] pub fn append_message (self , content : impl ToString , thought_signature : Option < String > , reasoning : Option < String > , reasoning_details : Option < Vec < ReasoningFull > > , usage : Usage , tool_records : Vec < (ToolCallFull , ToolResult) > , phase : Option < MessagePhase > ,) -> Self { let merged_reasoning_details = match (reasoning , reasoning_details) { (_ , Some (details)) => Some (details) , (Some (reasoning_text) , None) => Some (vec ! [ReasoningFull { text : Some (reasoning_text) , type_of : Some ("reasoning.text" . to_string ()) , .. Default :: default () }]) , (None , None) => None , } ; let mut message : MessageEntry = ContextMessage :: assistant (content , thought_signature , merged_reasoning_details , Some (tool_records . iter () . map (| record | record . 0 . clone ()) . collect :: < Vec < _ > > () ,) ,) . into () ; if let ContextMessage :: Text (ref mut text_msg) = message . message { text_msg . phase = phase ; } let tool_results = tool_records . iter () . map (| record | record . 1 . clone ()) . collect :: < Vec < _ > > () ; self . add_entry (message . usage (usage)) . add_tool_results (tool_results) } # [doc = " Returns the token count for context"] pub fn token_count (& self) -> TokenCount { let actual = self . messages . last () . as_ref () . and_then (| u | u . usage) . map (| u | u . total_tokens) . unwrap_or_default () ; match actual { TokenCount :: Actual (actual) if actual > 0 => TokenCount :: Actual (actual) , _ => TokenCount :: Approx (self . token_count_approx ()) , } } pub fn token_count_approx (& self) -> usize { self . messages . iter () . map (| m | m . token_count_approx ()) . sum :: < usize > () } # [doc = " Checks if reasoning is enabled by user or not."] pub fn is_reasoning_supported (& self) -> bool { self . reasoning . as_ref () . is_some_and (| reasoning | { if matches ! (reasoning . effort , Some (crate :: Effort :: None)) { return false ; } if reasoning . enabled . is_some () { return reasoning . enabled . unwrap_or_default () ; } reasoning . effort . is_some () || reasoning . max_tokens . is_some_and (| token | token > 0) }) } # [doc = " Returns a vector of user messages, selecting the first message from"] # [doc = " each consecutive sequence of user messages."] pub fn first_user_messages (& self) -> Vec < & ContextMessage > { if self . messages . is_empty () { return Vec :: new () ; } let mut result = Vec :: new () ; let mut is_user = false ; for msg in & self . messages { if msg . has_role (Role :: User) { if ! is_user { result . push (& * * msg) ; is_user = true ; } } else { is_user = false ; } } result } # [doc = " Returns the total number of messages in the context"] pub fn total_messages (& self) -> usize { self . messages . len () } # [doc = " Returns the count of user messages in the context"] pub fn user_message_count (& self) -> usize { self . messages . iter () . filter (| msg | msg . has_role (Role :: User)) . count () } # [doc = " Returns the count of assistant messages in the context"] pub fn assistant_message_count (& self) -> usize { self . messages . iter () . filter (| msg | msg . has_role (Role :: Assistant)) . count () } # [doc = " Returns the total count of tool calls across all messages"] pub fn tool_call_count (& self) -> usize { self . messages . iter () . filter (| msg | msg . has_tool_call ()) . map (| msg | { if let ContextMessage :: Text (text_msg) = & * * msg { text_msg . tool_calls . as_ref () . map_or (0 , | calls | calls . len ()) } else { 0 } }) . sum () } # [doc = " Checks if the model has changed from the previous assistant message."] # [doc = " Returns true if the previous assistant message has a different model"] # [doc = " than the provided current_model, or if there is no previous"] # [doc = " assistant message with a model."] # [doc = ""] # [doc = " This is used to determine whether to apply reasoning normalization - we"] # [doc = " only want to strip reasoning when switching models, not when"] # [doc = " continuing with the same model."] pub fn has_model_changed (& self , current_model : & ModelId) -> bool { let last_assistant_model = self . messages . iter () . rev () . find_map (| msg | { if let ContextMessage :: Text (text_msg) = & * * msg && text_msg . has_role (Role :: Assistant) { return text_msg . model . as_ref () ; } None }) ; match last_assistant_model { None => true , Some (prev_model) => prev_model != current_model , } } }